        const defaultSelectedUpper = getDefaultManufacturerSelectionUpper();
        const hasDefaultSelection = defaultSelectedUpper && defaultSelectedUpper.size > 0;

        for (const mfr of manufacturers) {
          const arr = byMfr.get(mfr) || [];
          const pricedLocal = arr.filter(p => Number.isFinite(p.price) && p.price > 0);
          const missingLocal = arr.filter(p => !(Number.isFinite(p.price) && p.price > 0));

          const mfrUpper = String(mfr).toUpperCase();
          const isSelected = !hasDefaultSelection || defaultSelectedUpper.has(mfrUpper);
          const initialVisible = isSelected ? true : 'legendonly';

          // Legend entry: always black marker; when toggled off, Plotly greys it.
          traces.push({
            type: 'scatter',
            mode: 'markers',
            name: mfr,
            legendgroup: mfr,
            showlegend: true,
            visible: initialVisible,
            // Plotly may hide legend items for traces with zero points.
            // Keep a single dummy point outside the fixed axis ranges.
            x: [0],
            y: [0],
            hoverinfo: 'skip',
            marker: { size: 8, color: 'rgb(0,0,0)' }
          });

          if (pricedLocal.length > 0) {
            traces.push({
              type: 'scattergl',
              mode: 'markers',
              name: mfr,
              legendgroup: mfr,
              showlegend: false,
              visible: initialVisible,
              x: pricedLocal.map(p => p.vd),
              y: pricedLocal.map(p => p.nd),
              customdata: pricedLocal.map(p => [
                p.name,
                p.manufacturer,
                Number.isFinite(p.price) ? p.price : null,
                p.nd,
                p.vd,
              ]),
              text: pricedLocal.map(makeHover),
              hoverinfo: 'text',
              marker: {
                size: 10,
                opacity: 0.9,
                color: pricedLocal.map(p => log10Safe(p.price)),
                cmin: pricedMinLog,
                cmax: pricedMaxLog,
                colorscale: PRICE_COLORSCALE,
                showscale: false,
                line: { width: 0 }
              }
            });
          }

          if (missingLocal.length > 0) {
            traces.push({
              type: 'scattergl',
              mode: 'markers',
              name: mfr,
              legendgroup: mfr,
              showlegend: false,
              visible: initialVisible,
              x: missingLocal.map(p => p.vd),
              y: missingLocal.map(p => p.nd),
              customdata: missingLocal.map(p => [
                p.name,
                p.manufacturer,
                null,
                p.nd,
                p.vd,
              ]),
              text: missingLocal.map(makeHover),
              hoverinfo: 'text',
              marker: {
                size: 10,
                opacity: 0.75,
                color: 'rgba(160,160,160,0.9)',
                line: { width: 0 }
              }
            });
          }
        }

        const layout = {
          margin: { l: 60, r: 30, t: 70, b: 55 },
          dragmode: 'select',
          xaxis: {
            title: { text: 'V<sub>d</sub>' },
            range: [105, 15],
            dtick: 10,
            zeroline: false,
            showgrid: true
          },
          yaxis: {
            title: { text: 'n<sub>d</sub>' },
            range: [1.3, 2.2],
            zeroline: false,
            showgrid: true
          },
          legend: { orientation: 'h', x: 0, y: 1.02, yanchor: 'bottom', groupclick: 'togglegroup' }
        };

        const config = {
          displayModeBar: true,
          responsive: true
        };

        const plotEl = document.getElementById('plot');

